package com.marketplace.adapters.out.persistence.category;
import com.marketplace.domain.category.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JpaCategoryRepositoryAdapter implements CategoryRepository { private final SpringDataCategoryRepository repo; public JpaCategoryRepositoryAdapter(SpringDataCategoryRepository repo){this.repo=repo;} public Category save(Category c){return domain(repo.save(entity(c)));} public Optional<Category> findById(Long id){return repo.findById(id).map(JpaCategoryRepositoryAdapter::domain);} public List<Category> findActive(){return repo.findByActiveTrueOrderByNameAsc().stream().map(JpaCategoryRepositoryAdapter::domain).toList();} private static CategoryJpaEntity entity(Category c){var e=new CategoryJpaEntity();e.id=c.id();e.name=c.name();e.description=c.description();e.active=c.active();e.createdAt=c.createdAt();return e;} private static Category domain(CategoryJpaEntity e){return Category.restore(e.id,e.name,e.description,e.active,e.createdAt);} }
